use std::io::{Read, Write};
use std::os::unix::net::UnixStream;

fn main() -> std::io::Result<()> {
    let (mut emisor, mut receptor) = UnixStream::pair()?;
    emisor.write_all(b"ARDREC")?;
    let mut recibido = [0_u8; 6];
    receptor.read_exact(&mut recibido)?;
    assert_eq!(&recibido, b"ARDREC");
    println!("ARDREC_RUST_UDS=PASS");
    Ok(())
}
